$path = Resolve-Path 'outputs/Excel Column Mapper.html'
$script:content = [IO.File]::ReadAllText($path)
function Replace-Section([string]$start,[string]$end,[string]$replacement) {
  $a = $script:content.IndexOf($start)
  $b = $script:content.IndexOf($end,$a)
  if ($a -lt 0 -or $b -lt 0) { throw "Could not locate section: $start" }
  $script:content = $script:content.Substring(0,$a) + $replacement + $script:content.Substring($b)
}
$script:content = $script:content.Replace('raw:false,blankrows:false','raw:false,blankrows:true')
$script:content = $script:content.Replace("'Designation':['job title','title','designation'", "'Designation':['job title','designation'")
$rows = @'
function headersOf(rows){let i=rows.findIndex(r=>r.some(x=>String(x??'').trim()!==''));if(i<0)return {headers:[],records:[],headerRow:0};let records=rows.slice(i+1).map((r,j)=>{r.__sourceRowNumber=i+j+2;return r;}).filter(r=>r.some(v=>v!==''&&v!=null));return {headers:rows[i].map(x=>String(x??'')),records,headerRow:i};}
function dsFrom(name,sheet,rows,fileSize=0){let p=headersOf(rows),id=crypto.randomUUID(),kept=p.records.slice(0,maxRows);kept.forEach(r=>r.__sourceRowId=id+':'+r.__sourceRowNumber);return {id,file:name,sheet,fileSize,headers:p.headers,rows:kept,originalCount:p.records.length,selected:true,map:{},priority:{},excluded:false};}
function normalize(s){return String(s??'').toLowerCase().replace(/[^a-z0-9]/g,'');}
function namePart(h){let n=normalize(h);if(['firstname','givenname','forename'].includes(n))return 'first';if(['lastname','familyname','surname'].includes(n))return 'last';return '';}
function personField(){return template?.fields.find(f=>normalize(f.name)==='contactperson')?.name||'';}
function fieldNamed(token){return template?.fields.find(f=>normalize(f.name)===normalize(token))?.name||'';}
function titleKind(v){let x=String(v??'').trim().toLowerCase().replace(/\.$/,'');if(/^(mr|mrs|ms|miss|mx|dr|prof|sir|madam|mstr)$/.test(x))return 'personal';if(/\b(manager|director|officer|engineer|head|lead|consultant|owner|founder|chief|president|executive|specialist|analyst|coordinator|administrator|advisor|partner|producer|editor|accountant|designer|developer|sales|marketing|finance|procurement|operations|compliance|product|technical|editorial|strategy|account|services|commercial|retail|event|project|program|supervisor|representative|architect|scientist|teacher|professor|business development|human resources|people|hr)\b/.test(x))return 'professional';return 'unknown';}
function suggest(h,d){let n=normalize(h),fields=template?.fields||[];if(n==='title'){let titleIdx=d?.headers.indexOf(h)??-1,vals=titleIdx<0?[]:d.rows.map(r=>r[titleIdx]).filter(v=>String(v??'').trim()!==''),kinds=vals.map(titleKind),professional=kinds.filter(x=>x==='professional').length,personal=kinds.filter(x=>x==='personal').length,unknown=kinds.filter(x=>x==='unknown').length;if(vals.length&&professional===vals.length){let f=fieldNamed('Designation');return f?{field:f,confidence:'High',reason:'Values look like professional job positions.'}:{field:'',confidence:'Low',reason:'Professional roles detected, but the template has no Designation field.'};}if(vals.length&&personal===vals.length){let f=fieldNamed('Title');return f?{field:f,confidence:'High',reason:'Values look like personal honorifics.'}:{field:'',confidence:'Low',reason:'Personal honorifics detected, but the template has no Title field.'};}return {field:'',confidence:'Low',reason:'Title values are mixed or unclear. Choose Title or Designation manually.'};}
let part=namePart(h);if(part){let paired=d?.headers.some(x=>namePart(x)===(part==='first'?'last':'first')),contact=personField();return paired&&contact?{field:'__COMBINE_CONTACT__',confidence:'High',reason:`Combine with the paired name field into ${contact}.`}:{field:'',confidence:'Low',reason:'A matching first-name or last-name column was not found.'};}
let exact=fields.find(f=>normalize(f.name)===n);if(exact)return {field:exact.name,confidence:'High',reason:'Exact standardized field name.'};for(let f of fields){let al=aliases[f.name]||[];if(al.some(a=>normalize(a)===n))return {field:f.name,confidence:'High',reason:`Recognized alias for ${f.name}.`};}
let best=null,score=0,second=0;for(let f of fields){let fn=normalize(f.name),sc=n&&fn&&(n.includes(fn)||fn.includes(n))?Math.min(n.length,fn.length)/Math.max(n.length,fn.length):0;if(sc>score){second=score;score=sc;best=f.name;}else if(sc>second)second=sc;}if(score>=.65&&score-second>=.12)return {field:best,confidence:'Medium',reason:`Similar column wording (${Math.round(score*100)}% name overlap); review the values.`};if(score>=.55)return {field:'',confidence:'Low',reason:'Several template fields may fit. Choose a destination manually.'};return {field:'',confidence:'Unmapped',reason:'No confident template match.'};}
'@
Replace-Section 'function headersOf(rows){' 'async function readTemplate(file){' $rows
$build = @'
function resolveTarget(d,row,target){let candidates=[];for(let h of d.headers){if(d.map?.[h]===target){let v=row[d.headers.indexOf(h)];candidates.push({source:h,value:v==null?'':v,priority:Number(d.priority?.[h])||d.headers.indexOf(h)+1});}}
if(normalize(target)==='contactperson'){let combined=d.headers.filter(h=>d.map?.[h]==='__COMBINE_CONTACT__'),firstH=combined.find(h=>namePart(h)==='first'),lastH=combined.find(h=>namePart(h)==='last');if(firstH||lastH){let first=firstH?String(row[d.headers.indexOf(firstH)]??'').trim():'',last=lastH?String(row[d.headers.indexOf(lastH)]??'').trim():'',value=[first,last].filter(Boolean).join(' ');candidates.push({source:[firstH,lastH].filter(Boolean).join(' + '),value,priority:Math.min(...[firstH,lastH].filter(Boolean).map(h=>Number(d.priority?.[h])||d.headers.indexOf(h)+1))});}}
candidates.sort((a,b)=>a.priority-b.priority);let nonempty=candidates.filter(c=>c.value!==''&&c.value!=null),value=nonempty.length?nonempty[0].value:'';let conflicts=nonempty.filter(c=>String(c.value)!==String(value));return {mapped:candidates.length>0,value,sources:candidates.map(c=>c.source),conflicts};}
function buildOutput(){let headers=[...template.fields.map(f=>f.name),'Source File Name','Source Sheet Name'],out=[],mapped=0,unmapped=0,conflicts=0,missingRows=0;let required=template.fields.filter(f=>f.required).map(f=>f.name);for(let d of datasets.filter(x=>x.selected)){for(let h of d.headers){if(d.map?.[h])mapped++;else unmapped++;}for(let row of d.rows){let o={};for(let h of headers)o[h]='';for(let f of template.fields){let resolved=resolveTarget(d,row,f.name);if(resolved.mapped)o[f.name]=resolved.value;conflicts+=resolved.conflicts.length;}o['Source File Name']=d.file;o['Source Sheet Name']=d.sheet;o.__sourceRowId=row.__sourceRowId;o.__sourceRowNumber=row.__sourceRowNumber;if(required.some(h=>o[h]===''||o[h]==null))missingRows++;out.push(o);}}let missing=template.fields.filter(f=>f.required&&!datasets.filter(d=>d.selected).some(d=>Object.values(d.map||{}).includes(f.name)||Object.values(d.map||{}).includes('__COMBINE_CONTACT__')&&normalize(f.name)==='contactperson')).length;let seen=new Set();for(let r of out){let key=headers.slice(0,-2).map(h=>String(r[h]??'')).join('\u001f');r.__duplicate=seen.has(key);seen.add(key);}return {headers,rows:out,mapped,unmapped,conflicts,missing,missingRows};}
function validateOutput(result){let sources=datasets.filter(d=>d.selected),sourceIds=new Map(),outputIds=new Map(),fieldStats=template.fields.map(f=>({field:f.name,expected:0,correct:0,mismatched:0,missing:0,unexpected:0})),mismatches=[],sourceStats=[];for(let d of sources)for(let row of d.rows)sourceIds.set(row.__sourceRowId,{d,row});for(let o of result.rows){let id=o.__sourceRowId;outputIds.set(id,(outputIds.get(id)||0)+1);}let missingIds=[...sourceIds.keys()].filter(id=>!outputIds.has(id)),additionalRows=result.rows.filter(o=>!sourceIds.has(o.__sourceRowId)),duplicateOutputIds=[...outputIds.values()].reduce((n,c)=>n+Math.max(0,c-1),0),matchedRecords=0,totalRowMismatches=0;for(let d of sources){let local={file:d.file,sheet:d.sheet,sourceRecords:d.rows.length,outputRecords:0,matchedRecords:0,mismatches:0,status:'PASS'};for(let row of d.rows){let id=row.__sourceRowId,outs=result.rows.filter(o=>o.__sourceRowId===id);local.outputRecords+=outs.length;if(outs.length!==1){local.mismatches++;totalRowMismatches++;mismatches.push({file:d.file,sheet:d.sheet,row:row.__sourceRowNumber,column:'(record)',field:'(record)',expected:'Exactly one output record',actual:String(outs.length),reason:outs.length?'Duplicate output record':'Source record missing'});continue;}let o=outs[0],rowErrors=0;for(let f of template.fields){let expected=resolveTarget(d,row,f.name);if(!expected.mapped)continue;let stat=fieldStats.find(x=>x.field===f.name);stat.expected++;let actual=o[f.name]==null?'':o[f.name],exp=expected.value==null?'':expected.value;if(String(actual)===String(exp)){stat.correct++;}else{stat.mismatched++;rowErrors++;let isMissing=exp!==''&&actual==='',isUnexpected=exp===''&&actual!=='';if(isMissing)stat.missing++;if(isUnexpected)stat.unexpected++;mismatches.push({file:d.file,sheet:d.sheet,row:row.__sourceRowNumber,column:expected.sources.join(' + '),field:f.name,expected:String(exp),actual:String(actual),reason:isMissing?'Expected value is missing':isUnexpected?'Unexpected value in output':'Value differs from mapped source or defined transformation'});}}
if(rowErrors===0){local.matchedRecords++;matchedRecords++;}else{local.mismatches++;totalRowMismatches++;}}let hasUnmapped=d.headers.some(h=>!d.map?.[h]),ambiguous=d.headers.some(h=>suggest(h,d).confidence==='Low'&&!d.map?.[h]);local.status=local.mismatches?'FAIL':(result.conflicts||hasUnmapped||ambiguous||result.missingRows)?'WARNING':'PASS';sourceStats.push(local);}
let expectedValues=fieldStats.reduce((n,f)=>n+f.expected,0),correctValues=fieldStats.reduce((n,f)=>n+f.correct,0),mismatchedValues=fieldStats.reduce((n,f)=>n+f.mismatched,0),missingValues=fieldStats.reduce((n,f)=>n+f.missing,0),unexpectedValues=fieldStats.reduce((n,f)=>n+f.unexpected,0),sourceRecords=sourceIds.size,outputRecords=result.rows.length,recordPct=sourceRecords?Math.max(0,(sourceRecords-missingIds.length)/sourceRecords*100):100,fieldPct=expectedValues?correctValues/expectedValues*100:100;let status=(missingIds.length||additionalRows.length||duplicateOutputIds||mismatchedValues||unexpectedValues)?'FAIL':(result.conflicts||result.unmapped||result.missingRows||sources.some(d=>d.headers.some(h=>suggest(h,d).confidence==='Low'&&!d.map?.[h])))?'WARNING':'PASS';return {status,sourceRecords,outputRecords,selectedWorksheets:sources.length,matchedRecords,recordsWithMismatches:totalRowMismatches,missingRecords:missingIds.length,additionalRecords:additionalRows.length,duplicateRecordsIntroduced:duplicateOutputIds,expectedValues,correctValues,mismatchedValues,missingValues,unexpectedValues,recordPct,fieldPct,fieldStats,sourceStats,mismatches,unmappedColumns:result.unmapped,sourceConflicts:result.conflicts,missingRequiredRows:result.missingRows};}
function renderValidationSummary(v){let cls=v.status.toLowerCase(),fmt=x=>Number(x).toLocaleString(),pct=x=>`${x.toFixed(1)}%`;return `<section class="card validation-card"><div class="row between"><div><h2>Testing &amp; validation summary</h2><p class="hint">Every selected source row is reconciled to an internal source-row identifier and checked against its standardized output fields.</p></div><span class="validation-status ${cls}">${v.status}</span></div><div class="validation-metrics"><div class="metric"><div class="m-label">Source → output records</div><strong>${fmt(v.sourceRecords)} → ${fmt(v.outputRecords)}</strong><small>${pct(v.recordPct)} reconciled by row ID</small></div><div class="metric"><div class="m-label">Field-level accuracy</div><strong>${pct(v.fieldPct)}</strong><small>${fmt(v.correctValues)} / ${fmt(v.expectedValues)} mapped values match (blank mapped values count as expected)</small></div><div class="metric"><div class="m-label">Matched records</div><strong>${fmt(v.matchedRecords)}</strong><small>${fmt(v.recordsWithMismatches)} records with mismatches</small></div><div class="metric"><div class="m-label">Record issues</div><strong>${fmt(v.missingRecords+v.additionalRecords+v.duplicateRecordsIntroduced)}</strong><small>${fmt(v.missingRecords)} missing · ${fmt(v.additionalRecords)} additional · ${fmt(v.duplicateRecordsIntroduced)} duplicate IDs</small></div></div><div class="stats"><span class="pill">${v.selectedWorksheets} selected worksheets</span><span class="pill">${fmt(v.mismatchedValues)} mismatched fields</span><span class="pill">${fmt(v.missingValues)} missing values</span><span class="pill">${fmt(v.unexpectedValues)} unexpected values</span><span class="pill">${fmt(v.sourceConflicts)} conflicting mapped values</span><span class="pill">${fmt(v.unmappedColumns)} unmapped columns</span></div><h3>Source worksheet results</h3><div class="tablewrap scroll"><table><thead><tr><th>Source dataset</th><th>Source records</th><th>Output records</th><th>Matched records</th><th>Mismatches</th><th>Status</th></tr></thead><tbody>${v.sourceStats.map(s=>`<tr><td>${esc(s.file)} · ${esc(s.sheet)}</td><td>${s.sourceRecords}</td><td>${s.outputRecords}</td><td>${s.matchedRecords}</td><td>${s.mismatches}</td><td><span class="validation-status ${s.status.toLowerCase()}">${s.status}</span></td></tr>`).join('')}</tbody></table></div><h3>Field accuracy</h3><div class="tablewrap scroll"><table><thead><tr><th>Standardized field</th><th>Expected values</th><th>Correct</th><th>Mismatched</th><th>Missing</th><th>Unexpected</th><th>Accuracy</th></tr></thead><tbody>${v.fieldStats.filter(f=>f.expected>0).map(f=>`<tr><td>${esc(f.field)}</td><td>${f.expected}</td><td>${f.correct}</td><td>${f.mismatched}</td><td>${f.missing}</td><td>${f.unexpected}</td><td>${pct(f.expected?f.correct/f.expected*100:100)}</td></tr>`).join('')}</tbody></table></div>${v.mismatches.length?`<details class="mismatch-details"><summary>Inspect ${fmt(v.mismatches.length)} mismatches</summary><div class="tablewrap scroll"><table><thead><tr><th>Source file</th><th>Worksheet</th><th>Source row</th><th>Source column</th><th>Standardized field</th><th>Expected</th><th>Actual output</th><th>Reason</th></tr></thead><tbody>${v.mismatches.map(m=>`<tr><td>${esc(m.file)}</td><td>${esc(m.sheet)}</td><td>${m.row}</td><td>${esc(m.column)}</td><td>${esc(m.field)}</td><td>${esc(m.expected)}</td><td>${esc(m.actual)}</td><td>${esc(m.reason)}</td></tr>`).join('')}</tbody></table></div></details>`:`<div class="notice success">No record or mapped-field mismatches were found. Unmapped columns, unresolved ambiguity, required-field blanks or conflicting source values may still produce WARNING status.</div>`}</section>`;}
'@
Replace-Section 'function buildOutput(){' 'function recordHistory(){' $build
$script:content = $script:content.Replace('let res=buildOutput();html=', 'let res=buildOutput(),validation=validateOutput(res);html=')
$script:content = $script:content.Replace('</section><section class="card"><h2>Download standardized data</h2>', '</section>${renderValidationSummary(validation)}<section class="card"><h2>Download standardized data</h2>')
$script:content = $script:content.Replace('function suggest(h){','function suggest(h,d){')
$script:content = $script:content.Replace('let s=suggest(h);d.map[h]=s.field;', 'let s=suggest(h,d);d.map[h]=s.field;')
$script:content = $script:content.Replace('let s=suggest(h);return `', 'let s=suggest(h,d);return `')
$script:content = $script:content.Replace('suggest(h).confidence', 'suggest(h,d).confidence')
$script:content = $script:content.Replace('function renderMapping(){let d=datasets.find(x=>x.id===$(\''#mapPick\'')?.value);if(!d)return;mappingConfirmed=', 'function renderMapping(){let d=datasets.find(x=>x.id===$(\''#mapPick\'')?.value);if(!d)return;mappingConfirmed=')
$script:content = $script:content.Replace('for(let h of d.headers)if(!(h in d.map)){let s=suggest(h);d.map[h]=s.field;}', 'for(let h of d.headers)if(!(h in d.map)){let s=suggest(h,d);d.map[h]=s.field;}')
$script:content = $script:content.Replace('<td><b>${esc(h)}</b></td><td><select data-header=', '<td><b>${esc(h)}</b></td><td><select data-header=')
$style = @'
.validation-card h3{font-size:15px;margin:20px 0 8px}.validation-metrics{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:10px;margin:14px 0}.validation-metrics .metric{padding:13px}.validation-metrics strong{font-size:20px}.validation-metrics small{display:block;color:#64748b;font-size:11px;line-height:1.4;margin-top:5px}.validation-status{display:inline-flex;padding:5px 10px;border-radius:20px;font-weight:750;font-size:11px;letter-spacing:.45px;background:#e5e7eb;color:#475569}.validation-status.pass{background:#d1fae5;color:#08734f}.validation-status.warning{background:#fef3c7;color:#946200}.validation-status.fail{background:#ffe4e6;color:#b4233a}.mismatch-details{border:1px solid #e8ebf2;border-radius:9px;padding:12px;margin-top:16px}.mismatch-details summary{font-weight:650;cursor:pointer}.notice.validation-warning{background:#fff7e8;color:#875400}@media(max-width:850px){.validation-metrics{grid-template-columns:repeat(2,minmax(0,1fr))}}
'@
$script:content = $script:content.Replace('</style></head>', $style + '</style></head>')
[IO.File]::WriteAllText($path,$script:content,[Text.UTF8Encoding]::new($false))
